#include <cstdio>
#include <cmath>
#include <algorithm>
#include <queue>
#include <unordered_set>

#define MAX_N 5000

using namespace std;

int N;
int E;
vector<int> in[MAX_N + 1];
vector<int> out[MAX_N + 1];
queue<int> S;
queue<int> L;

bool multi_flag;

// Using unordered_set for O(1) average time complexity for existence checks
unordered_set<int> in_set[MAX_N + 1];

void populate_in_set() {
    for (int v = 1; v <= N; v++) {
        in_set[v].insert(in[v].begin(), in[v].end());
    }
}

bool in_exist(int v) {
    return !in_set[v].empty() && in_set[v].find(-1) == in_set[v].end();
}

void solve() {
    for (int i = 1; i <= N; i++) {
        if (!in_exist(i)) S.push(i);
    }

    while (!S.empty()) {
        int u = S.front(); S.pop();
        L.push(u);
        int entered = 0;

        for (int to : out[u]) {
            in_set[to].erase(u);
            if (in_exist(to) == false) {
                S.push(to);
                entered++;
            }
        }
        if (entered >= 2) multi_flag = true;
    }
}

int main() {
    scanf("%d", &N);
    scanf("%d", &E);
    int _u, _v;
    for (int i = 0; i < E; i++) {
        scanf("%d%d", &_u, &_v);
        in[_v].push_back(_u);
        out[_u].push_back(_v);
    }
    populate_in_set(); // Populate the unordered_set
    solve();
    while (!L.empty()) {
        printf("%d\n", L.front()); L.pop();
    }
    puts(multi_flag ? "1" : "0");
    return 0;
}

